import{_ as i,l as o,o as e,c as s,v as t,p as l,x as n,d as E,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const S=JSON.parse('{"title":"距离法配对","description":"","frontmatter":{"title":"距离法配对","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/distance-pairs.md","filePath":"quant/distance-pairs.md","lastUpdated":1789023840000}'),h={name:"quant/distance-pairs.md"};function c(B,a,u,m,A,_){const r=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="距离法配对" tabindex="-1">距离法配对 <a class="header-anchor" href="#距离法配对" aria-label="Permalink to &quot;距离法配对&quot;">​</a></h1><div class="epigraph"><p>在形成期把价格标准化后，选出平方偏差之和最小的配对；在随后的交易期，当价差偏离历史两个标准差时开仓，并在回归或期末强平。</p><footer>—— Gatev, Goetzmann &amp; Rouwenhorst, Pairs Trading: Performance of a Relative-Value Arbitrage Rule, Review of Financial Studies, 2006</footer></div><p>距离法是统计套利里最能被独立复制的规则之一：不估计协整向量，不估计因子，只用价格路径的欧氏距离选对。Gatev、Goetzmann 与 Rouwenhorst（下称 GGR）把 1962–2002 年美股写成 12 个月形成、6 个月交易的制度，开仓阈值是形成期价差的两个标准差。它后来被当成「配对交易有效」的证据引用，但原文报告的是扣除保守交易成本之后仍然存在、且随时间衰减的超额；Do 与 Faff 随后证明，成本假设一紧，许多年份的净收益就消失。距离小不等于协整，更不等于有容量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>相对价值策略需要一种事前可计算的「谁和谁像」。协整检验在短形成期里势低、多重检验严重；行业内两两组合的数量是 \\(N(N-1)/2\\)，你总会找到样本内残差平稳的对。GGR 的问题设定是：若只用公开价格、用一个不依赖回归斜率的距离，相对价值规则是否还能产生正的平均收益。他们刻意避免复杂计量，以便规则像 Jegadeesh–Titman 动量那样可复述。</p><p>距离的定义是标准化价格（形成期第一个交易日为 1）的平方差之和。这与相关系数不同：两条高度相关但漂移幅度不同的路径，距离仍可以很大。它与协整也不同：两条 I(1) 且 \\(\\beta\\neq 1\\) 的价格，标准化后未必近。方法选择的是「历史走在一起」的对，赌的是这种邻近会在交易期延续。若邻近来自共同因子或指数权重，而不是可交易的残差平稳，距离法就会在因子拥挤时变成一篮子隐形的因子赌注。</p><h3 id="形成期最短距离不是经济均衡" tabindex="-1">形成期最短距离不是经济均衡 <a class="header-anchor" href="#形成期最短距离不是经济均衡" aria-label="Permalink to &quot;形成期最短距离不是经济均衡&quot;">​</a></h3><p>最小 SSD 只说明过去 12 个月两条标准化曲线贴得近。公司可能同行业、同指数、同做市商库存，或只是碰巧。交易期若发生<a href="/quant/cointegration-break">协整破裂</a>，距离近的对往往是同一冲击的两边，价差会一起裂开而不是回归。GGR 用行业内配对作为稳健性，正是担心跨行业的伪近。即便行业内，并购传闻、成分股调整仍会把「最近的邻居」变成事件驱动腿。</p><p><span class="marginnote">GGR 开仓用的两个标准差来自形成期价差，不是交易期的滚动 Z-score。把规则改成滚动 20 日 Z-score，已经不是原文策略，样本内表现不可拿 2006 年的表去背书。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>标准复制。形成期 \\(T_f=12\\) 个月，对每只股票把价格除以期初价格。对所有候选对计算</p> \\[\\mathrm{SSD}_{ij}=\\sum_{t\\in T_f}(P_{i,t}-P_{j,t})^2. \\]<p>选 SSD 最小的 \\(n\\) 对（原文常用前 5、20 对）进入交易期 \\(T_t=6\\) 个月。价差 \\(e_t=P_{i,t}-P_{j,t}\\)（仍用各自形成期标准化，或在交易期继续用价格比，复制时必须固定一种）。当 \\(|e_t|\\) 超过形成期 \\(\\hat\\sigma_e\\) 的两倍，做多便宜腿、做空贵腿，等权、美元中性。价差回到形成期均值则平仓；若到交易期末仍未回归，强制平仓——这是时间止损，不是价格止损。</p><p>现金与成交约定。GGR 用次日可交易价格，避免用信号当天收盘价。等待期与停牌会减少成交次数，从而减少账面次数、也减少成本次数。报告应区分「有信号」与「实际开得了仓」。重叠的形成/交易日历使任意一天都有多个 vintage 的对在跑，组合收益是这些 vintage 的平均，不是单一 6 个月的一条路径。</p><h3 id="成本、匹配失败与衰减" tabindex="-1">成本、匹配失败与衰减 <a class="header-anchor" href="#成本、匹配失败与衰减" aria-label="Permalink to &quot;成本、匹配失败与衰减&quot;">​</a></h3><p>原文用单边 8 个基点一类的保守假设，发现扣费后仍有超额，但超额在样本后半弱于前半。Do 与 Faff（2010, 2012）把价差、佣金、卖空费用收紧，并考虑开仓时两腿无法同时成交（stale quotes、涨跌停），净收益大幅下降。Engelberg、Gao 与 Jagannathan 指出，配对利润集中在信息事件附近：那不是平稳残差的回归，而是对新闻的错误定价与随后的共同反应。把距离法写成「无信息的数学套利」，与分解证据不符。</p><p><span class="marginnote">两腿的流动性不对称会把距离法变成隐性的流动性供给：便宜腿往往更窄、更难买，贵腿更好空。净收益里有一部分是<a href="/quant/short-term-reversal">短期反转</a>与价差反弹，应用中点或次日开盘检验。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>若两条价格共享一个随机趋势且标准化后 \\(\\beta\\approx 1\\)，SSD 小与协整近乎同事。此时开仓近似在交易平稳价差，期望来自误差修正。若共享的是可交易因子（行业、质量、动量），距离近只是因子暴露相近，两倍标准差开仓是在做空一个相对的特异冲击；冲击若来自共同因子的进一步发散（拥挤、赎回），价差不会回归。Khandani 与 Lo 描述的 2007 年量化平仓，会让许多「历史上最近的邻居」同时走扩。</p><p>另一个机制是指数与 ETF 的一揽子交易：成分股被同时买卖，标准化价格短期内被钉在一起，SSD 变小，交易期若碰上再平衡反向冲击，距离法会在错误的一侧。这与<a href="/quant/etf-arb">ETF 与成分股</a>的套利通道相反——那里有申赎收敛，这里没有。</p><h3 id="为何规则简单仍会被容量打穿" tabindex="-1">为何规则简单仍会被容量打穿 <a class="header-anchor" href="#为何规则简单仍会被容量打穿" aria-label="Permalink to &quot;为何规则简单仍会被容量打穿&quot;">​</a></h3><p>简单规则的优点是可复制，缺点是大家都复制。形成期公开、阈值公开、持有期公开，意味着信号高度拥挤。容量不取决于「历史上 SSD 最小的那 20 对有多赚钱」，而取决于这些对在开仓日的 ADV、借券深度、以及有多少资本用同一张表。扩大 \\(n\\) 会迅速吃进距离更远、均值回归更弱的对；缩小 \\(n\\) 则把全部资本堆在少数名字上，冲击平方上升。GGR 的等权、日频、中小盘都进样本，纸面换手远高于可执行换手。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>不要把距离法升级成「先做协整检验再过滤」却仍引用 GGR 的收益表：那是另一种多重检验。也不要把 SSD 换成相关系数或回归 \\(R^2\\) 却声称复制了 RFS 2006。A 股需要额外处理涨跌停：形成期若含一字板，标准化路径被钉死，SSD 会假小。卖空约束让空腿经常开不出，策略会退化成单边做多「便宜腿」，那是价值或反转，不是配对。</p><p>成本模型至少要包括：有效价差而非报价一半、两腿同时成交的失败率、6 个月强制平仓日的流动性（往往集中）、以及借券费随持有延长而上升。时间止损会在价差最宽时成交，冲击最差。若你改用价格止损，又会锁定「未回归就认赔」的负偏，见<a href="/quant/statarb-stops">止损与时间止损</a>。任何一种改动都要单独回测，不能借用 GGR 扣费后的均值。</p><p><span class="marginnote">GGR 样本截止 2002。之后 ETF 普及、做市电子化、配对拥挤，都改变了同一规则的可交易性。复制应报告子样本，而不是把 1962–2002 的均值写成当前期望。</span></p>',26)),(e(),l(d,null,{default:n(()=>[p(r,{id:"mermaid-74",class:"mermaid",graph:"flowchart%20LR%0A%20%20F%5B%2212%20%E4%B8%AA%E6%9C%88%E5%BD%A2%E6%88%90%E6%9C%9F%22%5D%20--%3E%20SSD%5B%22%E6%A0%87%E5%87%86%E5%8C%96%E4%BB%B7%E6%A0%BC%20SSD%22%5D%0A%20%20SSD%20--%3E%20SEL%5B%22%E9%80%89%E5%87%BA%E8%B7%9D%E7%A6%BB%E6%9C%80%E5%B0%8F%E7%9A%84%20n%20%E5%AF%B9%22%5D%0A%20%20SEL%20--%3E%20T%5B%226%20%E4%B8%AA%E6%9C%88%E4%BA%A4%E6%98%93%E6%9C%9F%22%5D%0A%20%20T%20--%3E%20SIG%5B%22%E4%BB%B7%E5%B7%AE%E8%B6%85%E8%BF%87%E5%BD%A2%E6%88%90%E6%9C%9F%202%CF%83%22%5D%0A%20%20SIG%20--%3E%20OPEN%5B%22%E6%AC%A1%E6%97%A5%E5%BC%80%E4%BB%93%EF%BC%9A%E5%A4%9A%E4%BE%BF%E5%AE%9C%20%2F%20%E7%A9%BA%E6%98%82%E8%B4%B5%22%5D%0A%20%20OPEN%20--%3E%20CLOSE%5B%22%E5%9B%9E%E5%BD%92%E5%9D%87%E5%80%BC%E6%88%96%E6%9C%9F%E6%9C%AB%E5%BC%BA%E5%B9%B3%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>距离法用形成期标准化价格的平方偏差选对，用形成期两个标准差开仓，用回归或期末强平结束——这是 GGR（2006）的可复制规则，不是协整估计。</li><li>距离近只说明历史路径贴近，不保证交易期残差平稳，也不提供指数套利那种制度收敛。</li><li>扣费后的超额对成本假设、同时成交与样本区间敏感；Do–Faff 与事件分解表明利润会衰减、并混有信息事件。</li><li>容量受 ADV、借券与拥挤约束；扩大配对数会稀释信号，缩小则放大冲击。</li><li>出处：Gatev, Goetzmann and Rouwenhorst, <em>Review of Financial Studies</em>, 2006；Do and Faff, <em>Financial Analysts Journal</em>, 2010 与 <em>Journal of Financial Research</em>, 2012。</li></ul>',2))])}const D=i(h,[["render",c]]);export{S as __pageData,D as default};
